    "slug": "cash-flow-problems",
    "calculatorSlug": "cash-flow-forecast-template",
    "title": "Cash Flow Problems: Causes, Solutions and a Recovery Plan",
    "seoTitle": "Cash Flow Problems: Causes & Recovery Plan",
    "description": "Diagnose cash flow problems with a four-week example, tested timing fixes, a weekly review routine and an editable recovery action plan for your business.",
    "metaDescription": "Diagnose cash flow problems with a four-week example, tested timing fixes, a weekly review routine and an editable recovery action plan for your business.",
