    "cluster": "cash-flow-reporting",
    "image": "/images/blog/cash-flow-problems-editorial-20261025.webp",
    "alt": "Two coworkers reviewing invoices and a weekly payment calendar",
    "imageCaption": "AI-generated editorial image; all figures in the guide are separate, original fictional examples.",
